contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address spender, address _from, address _to, uint256 _amount) public {
        require(_to != address(0));
        require(_to != _from);

        uint256 otherBefore = c.allowance(_from, spender);
        uint256 fromBefore = c.balanceOf(_from);
        uint256 toBefore = c.balanceOf(_to);

        require(_from != address(this));
        require(otherBefore <= fromBefore);

        address owner = c.owner();
        require(owner == address(this));

        c.transfer(_from, _amount);

        c.approve(spender, otherBefore);

        uint256 fromBefore2 = c.balanceOf(_from);
        uint256 toBefore2 = c.balanceOf(_to);

        bool success;
        try c.transferFrom(_from, _to, _amount) returns (bool ok) {
            success = ok;
        } catch {
            success = false;
        }

        uint256 otherAfter = c.allowance(_from, spender);
        uint256 fromAfter = c.balanceOf(_from);
        uint256 toAfter = c.balanceOf(_to);

        if (success) {
            assert(otherAfter == otherBefore);
            assert(fromAfter == fromBefore2 - _amount);
            assert(toAfter == toBefore2 + _amount);
        } else {
            assert(otherAfter == otherBefore);
            assert(fromAfter == fromBefore2);
            assert(toAfter == toBefore2);
        }
    }

    receive() external payable {}
}

