    function run(uint256 _value) public payable {
        uint256 supplyBefore = c.totalSupply();
        uint256 balBefore = c.balanceOf(address(this));
        require(_value <= balBefore, "insufficient balance for burn");
        bool reverted;
        try c.burn(_value) { reverted = false; } catch { reverted = true; }
