contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bool attacker) public {
        bool reverted;
        bool initial = c.distributionFinished();
        if (attacker) {
            reverted = false;
        } else {
            reverted = true;
        }
        if (attacker) {
            try c.finishDistribution() {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            c.finishDistribution();
            reverted = false;
        }
        if (attacker) {
            assert(reverted && !c.distributionFinished() && initial == c.distributionFinished());
        } else {
            assert(!reverted && c.distributionFinished() && initial == false);
        }
    }
}

